import{_ as o,l as r,o as a,c as n,v as t,p as d,x as i,d as p,i as s,S as u}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"光瞳填充比","description":"","frontmatter":{"title":"光瞳填充比","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pupil-fill-ratio.md","filePath":"litho/pupil-fill-ratio.md","lastUpdated":1789023840000}'),h={name:"litho/pupil-fill-ratio.md"};function E(F,e,P,c,A,_){const l=r("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="光瞳填充比" tabindex="-1">光瞳填充比 <a class="header-anchor" href="#光瞳填充比" aria-label="Permalink to &quot;光瞳填充比&quot;">​</a></h1><div class="epigraph"><p>光源有尺寸和发散，光瞳只有那么大。填充比是 etendue 匹配：填太满，相干性差、对比掉；填不满，光子浪费在光阑上。</p><footer>—— 对照 EUV 源–光瞳 etendue；ASML 对 pupil fill 与照明的公开讨论</footer></div><p><a href="/litho/ring-field">上一课</a>把瞬时场收成弧。缺口是弧上每一物点对应的照明光瞳：等离子体和收集镜送来的 etendue，有多少能填进投影光瞳。具体开环形、极子还是 FlexPupil，留给<a href="/litho/euv-illumination-settings">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>环形场规定了物面几何。成像对比还取决于部分相干：光瞳填充比（pupil fill ratio, PFR）刻画源在投影光瞳里占的面积分数。LPP 等离子体不是点，收集椭球把它成像到 IF，IF 有有限尺寸和角分布。投影 NA 在掩模侧再被倍率缩小。etendue 不匹配时，要么源被光阑切掉（IF 功率浪费），要么填充过大（σ 太大，NILS 掉），要么填充过小（等效相干太强，斑纹和通过焦点摆动）。</p><p>缺口是 PFR 作为源与照明之间的合同，不是再画一条弧。收集镜变脏会改有效源形状，PFR 和 σ 图一起漂——清洗课的光瞳判据在这里变成成像量。</p><p><span class="marginnote">DUV 准分子经均光后可以近似均匀填瞳。EUV 的 IF 是二次源，填充受收集立体角和等离子体尺寸限制，不能当成无限可整形的朗伯灯。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义上，PFR 是照明在光瞳平面占用的通光面积相对完整光瞳的比；与传统 σ（外半径/NA）相关，但离轴极子、环照明要用面积比而不是单半径。设计：先按关键层 NILS 选目标填充，再反推 IF 尺寸和收集 NA 是否供得上。源变大有利于功率和稳定，不利于小填充的极子；源变小有利于 SMO 的激进光瞳，不利于 CE 和击中率。</p><p>计量：光瞳传感器看填充与均匀。剂量环只看积分能量会掩盖 PFR 漂移。SMO 换设置等于换 PFR 目标，必须确认源 etendue 仍覆盖，否则光阑吃光，产能暗中下降。</p><h3 id="etendue-守恒没有免费整形" tabindex="-1">etendue 守恒没有免费整形 <a class="header-anchor" href="#etendue-守恒没有免费整形" aria-label="Permalink to &quot;etendue 守恒没有免费整形&quot;">​</a></h3><p>照明可以把 IF 重成像、切光瞳，不能把相空间体积变小而不丢光。激进偶极要的是小填充、特定方位；源若天生填得更满，多出的 etendue 只能挡在光阑上，等于 IF 功率打折。功率路线加收集立体角，会直接顶高 PFR 下限，与 SMO 抢预算。</p>',12)),(a(),d(u,null,{default:i(()=>[s(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ET%5B%22%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%20etendue%22%5D%20--%3E%20IF%5B%22IF%20%E5%B0%BA%E5%AF%B8%E4%B8%8E%E8%A7%92%22%5D%0A%20%20IF%20--%3E%20PFR%5B%22%E5%85%89%E7%9E%B3%E5%A1%AB%E5%85%85%E6%AF%94%22%5D%0A%20%20PFR%20--%3E%20COH%5B%22%E9%83%A8%E5%88%86%E7%9B%B8%E5%B9%B2%20%2F%20NILS%22%5D%0A%20%20PFR%20--%3E%20LOSS%5B%22%E5%85%89%E9%98%91%E6%88%AA%E6%96%AD%E5%88%99%E4%B8%A2%E5%8A%9F%E7%8E%87%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>部分相干成像里，源点互不相干，光瞳填充决定哪些衍射级对能干涉。填充增大，高频级的相干传递下降，解析力的「可用」部分变少，但斑纹和对准灵敏度往往改善。EUV 光子贵，既不能把功率扔在光瞳外，也不能为了 NILS 把填充收到源供不上。PFR 是这条刀刃。</p><p>收集镜径向 \\(R\\) 不均等于给源加了一张渐变滤光片，填充形状畸变。磁场碎屑抑制或气锁挡板若挡掉一部分立体角，等效缩小 etendue，PFR 上限下降。功率路线加立体角，会直接顶到本课的匹配。</p><p><span class="marginnote">不要把 PFR 和「光源功率百分比」混为一谈。功率可以很高但填错地方；也可以 PFR 漂亮但带内瓦数不够。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不罗列量产极子角度表，下一课才谈 EUV 照明设置。不重写 TCC 推导。PFR 合格而填充形状畸变，SMO 仍会失败——面积比不是 σ 图。出处：ASML pupil/illumination 公开讨论；Bakshi 源与照明；etendue 匹配通识。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PFR 是源 etendue 与投影光瞳的匹配，决定部分相干和有多少 IF 功率被光阑扔掉。</li><li>收集镜老化改变有效源形状，从而改变 PFR。</li><li>下一课在给定 PFR 预算下选具体照明。</li><li>出处：ASML；Bakshi。</li></ul>',8))])}const B=o(h,[["render",E]]);export{m as __pageData,B as default};
